-- Rasoi Crate: sample data for the SQL Path project "Customer retention study".
-- A fictional Indian meal-kit subscription company. Signups and monthly billing from January 2024
-- to June 2025; the data ends on 2025-06-30. Synthetic data, generated by a fixed-seed script.
-- Amounts are whole Indian rupees. Months are text (YYYY-MM); dates are text (YYYY-MM-DD).
-- Things to watch: some signups never paid; a failed payment can be retried and paid in the same month;
-- first boxes are discounted or free (amount 0); some customers cancel and come back months later.

CREATE TABLE plans (
  plan_id        INTEGER PRIMARY KEY,
  name           TEXT    NOT NULL,
  meals_per_week INTEGER NOT NULL,
  people         INTEGER NOT NULL,
  monthly_price  INTEGER NOT NULL
);


-- channel: how the customer found us. first_offer: 'none', 'half_off_first_box' or 'free_first_box'.
CREATE TABLE customers (
  customer_id INTEGER PRIMARY KEY,
  signup_date TEXT    NOT NULL,
  city        TEXT    NOT NULL,
  channel     TEXT    NOT NULL,
  plan_id     INTEGER NOT NULL REFERENCES plans (plan_id),
  first_offer TEXT    NOT NULL
);


-- One row per billing attempt. status is 'paid' or 'failed'; a failed attempt may be retried in the same month.
CREATE TABLE payments (
  payment_id    INTEGER PRIMARY KEY,
  customer_id   INTEGER NOT NULL REFERENCES customers (customer_id),
  billing_month TEXT    NOT NULL,
  amount        INTEGER NOT NULL,
  status        TEXT    NOT NULL
);


-- One row each time a customer cancels (a customer who comes back and cancels again has two rows).
CREATE TABLE cancellations (
  customer_id  INTEGER NOT NULL REFERENCES customers (customer_id),
  cancelled_on TEXT    NOT NULL,
  reason       TEXT    NOT NULL
);


CREATE TABLE support_tickets (
  ticket_id        INTEGER PRIMARY KEY,
  customer_id      INTEGER NOT NULL REFERENCES customers (customer_id),
  opened_on        TEXT    NOT NULL,
  category         TEXT    NOT NULL,
  hours_to_resolve INTEGER NOT NULL
);


-- Acquisition spend per month and channel. For referrals it is the credit paid to the referrer.
CREATE TABLE marketing_spend (
  month   TEXT    NOT NULL,
  channel TEXT    NOT NULL,
  spend   INTEGER NOT NULL,
  PRIMARY KEY (month, channel)
);

